    <style>
        :root{color-scheme:light;--green-900:#0c5c38;--green-800:#147247;--green-100:#e7f5ec;--green-50:#f4faf6;--surface:#fff;--border:#d3e3d8;--text:#10291c;--muted:#65766b;--danger:#b42318;--warning:#b45309;--shadow:0 16px 38px rgba(8,59,38,.09)}
        *{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--text);background:#eef7f1;font-family:'Outfit',system-ui,sans-serif}button,input,select,textarea{font:inherit}
