        .admin-brand,.admin-session,.sidebar-brand,.sidebar-link,.page-head,.user-cell,.action-cell,.detail-head,.panel-head{display:flex;align-items:center}.admin-brand{gap:12px;color:inherit;text-decoration:none}.admin-brand-mark,.sidebar-mark{display:grid;place-items:center;flex:0 0 auto;border-radius:8px;font-weight:900}.admin-brand-mark{width:48px;height:48px;color:var(--green-900);background:#fff}.admin-brand-copy,.sidebar-copy{display:grid;gap:2px}.admin-brand-copy strong{font-size:1rem}.admin-brand-copy span,.sidebar-copy span{font-size:.82rem;opacity:.82}.admin-session{justify-content:flex-end;gap:10px;flex-wrap:wrap}.admin-chip{padding:8px 12px;border:1px solid rgba(255,255,255,.18);border-radius:999px;background:rgba(255,255,255,.1);font-size:.8rem;font-weight:700}.logout-form,.inline-form{margin:0}.logout-button{min-height:38px;padding:0 17px;border:0;border-radius:999px;color:var(--green-900);background:#fff;font-weight:800;cursor:pointer}
