        .admin-main{min-width:0;padding:28px}.page-shell{width:min(1320px,100%);margin:0 auto}.page-head{justify-content:space-between;gap:18px;margin-bottom:18px}.page-title span,.panel-kicker,.field label{color:var(--green-800);font-size:.72rem;font-weight:800;letter-spacing:.07em;text-transform:uppercase}.page-title h1{margin:4px 0 0;font-size:clamp(1.65rem,3vw,2.2rem)}.page-meta{padding:9px 13px;border:1px solid var(--border);border-radius:999px;background:#fff;color:var(--green-900);font-size:.82rem;font-weight:700}
